import { Alert, Button, cn, Field, Input, Spinner } from '@dv/ui';
import {
  Check,
  Circle,
  Copy,
  ExternalLink,
  Landmark,
  Paperclip,
  QrCode,
  Wallet,
  X,
} from 'lucide-react';
import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import {
  useCreateDepositRequest,
  usePaymentMethods,
  type PaymentAccountOptionDto,
  type PaymentMethodOptionDto,
  type WalletFeaturesDto,
} from '@/entities/wallet/api';
import { formatCurrency } from '@/shared/lib/format';
import { AccountBarcode } from './AccountBarcode';
import { DepositDocuments, missingDocumentItems } from './DepositDocuments';
import { useApiErrorMessage } from '@/shared/lib/useApiError';

interface Props {
  /** The balance being topped up; its payment methods are the ones offered. */
  currencyId: string;
  /** Its code, for the amount box and the limits. */
  currency: string;
  features: WalletFeaturesDto;
  /** Leaves the form from its first step. */
  onCancel: () => void;
  onSubmitted: () => void;
  /**
   * Fills the amount in advance. Set when arriving from a payment that came up short, so the
   * figure somebody needs is not one they have to work out and retype.
   */
  initialAmount?: number;
}

const MAX_FILES = 5;
const MAX_FILE_BYTES = 5 * 1024 * 1024;

/**
 * Adding funds to one balance through a configured payment method — the Add funds page's form.
 *
 * Three steps, because they answer three different questions: what kind of payment, then which
 * provider of that kind, then what the applicant actually did. Kind first because it is how
 * somebody decides — "I will pay by bank transfer" comes before "which of your bank accounts" —
 * and because a flat list of every method mixed those two decisions into one, which only worked
 * while there were a handful of methods.
 *
 * What the last step asks for — whether an account has to be picked, whether a receipt must be
 * attached — comes from the method's type, so the form matches whatever an administrator
 * configured without knowing any provider by name.
 *
 * The applicant is not asked for a transfer reference. Reading one off a slip is the easiest thing
 * in this form to get wrong, and it was never what protected the money: the reviewer records the
 * reference they matched on the statement when they approve, and that is the one checked for
 * having been credited before.
 */
export function DepositForm({
  currencyId,
  currency,
  features,
  onCancel,
  onSubmitted,
  initialAmount,
}: Props) {
  const { t, i18n } = useTranslation();
  const locale = i18n.resolvedLanguage ?? 'en';
  const toMessage = useApiErrorMessage();

  const methods = usePaymentMethods(currencyId);
  const create = useCreateDepositRequest();

  const [typeId, setTypeId] = useState<string | null>(null);
  const [methodId, setMethodId] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string | null>(null);
  const [amount, setAmount] = useState('');
  const [note, setNote] = useState('');
  const [files, setFiles] = useState<File[]>([]);
  const [documentFiles, setDocumentFiles] = useState<Record<string, File[]>>({});
  const [documentValues, setDocumentValues] = useState<Record<string, string>>({});

  // Switching currency starts over: its methods, accounts and documents are different ones.
  useEffect(() => {
    setTypeId(null);
    setMethodId(null);
    setAccountId(null);
    // Prefilled where the caller knows the figure; still editable, since somebody may want to add
    // more than the shortfall while they are here.
    setAmount(initialAmount && initialAmount > 0 ? String(initialAmount) : '');
    setNote('');
    setFiles([]);
    setDocumentFiles({});
    setDocumentValues({});
    create.reset();
    // `create` is a stable mutation object; re-running on its identity would clear the error the
    // applicant is still reading.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currencyId, initialAmount]);

  // Memoised so the grouping below is not rebuilt on every render by a fresh empty array.
  const available = useMemo(() => methods.data ?? [], [methods.data]);
  const method = available.find((option) => option.id === methodId) ?? null;

  // Grouped in the order the server sent them, so the sort an administrator set on the type
  // catalogue is the order the applicant sees.
  const types = useMemo(() => {
    const grouped = new Map<
      string,
      { id: string; name: string; methods: PaymentMethodOptionDto[] }
    >();

    for (const option of available) {
      const existing = grouped.get(option.paymentMethodTypeId);
      if (existing) existing.methods.push(option);
      else {
        grouped.set(option.paymentMethodTypeId, {
          id: option.paymentMethodTypeId,
          name: option.typeName,
          methods: [option],
        });
      }
    }

    return [...grouped.values()];
  }, [available]);

  const type = types.find((option) => option.id === typeId) ?? null;

  const step = method ? 3 : type ? 2 : 1;

  function chooseType(id: string) {
    setTypeId(id);
    // A method from the previous type would now be the wrong answer to a question nobody asked.
    setMethodId(null);
    setAccountId(null);
  }

  function goBack() {
    if (method) {
      setMethodId(null);
      setAccountId(null);

      // A type with a single provider selects it automatically, so stepping back onto that screen
      // would re-select it and land straight back here. Go back to the question that still has
      // more than one answer.
      if (type && type.methods.length === 1) setTypeId(null);
      return;
    }

    if (type) {
      setTypeId(null);
      return;
    }

    onCancel();
  }

  // A type offering exactly one provider has nothing to choose between; asking anyway is a screen
  // whose only answer is already known.
  useEffect(() => {
    if (type && type.methods.length === 1) setMethodId(type.methods[0]!.id);
  }, [type]);

  // A method with exactly one account has nothing to choose; preselecting it removes a step that
  // would only ever have one answer.
  useEffect(() => {
    if (!method?.requiresAccountNumber) {
      setAccountId(null);
      return;
    }

    setAccountId(method.accounts.length === 1 ? method.accounts[0]!.id : null);
  }, [method]);

  // Another method asks for other documents; what was attached for the last one does not carry.
  useEffect(() => {
    setDocumentFiles({});
    setDocumentValues({});
  }, [methodId]);

  const documents = useMemo(() => method?.requiredFiles ?? [], [method]);

  const parsed = Number(amount);
  const isNumeric = amount.trim() !== '' && Number.isFinite(parsed);
  const belowMinimum = isNumeric && parsed < features.minimumRequestAmount;
  const aboveMaximum = isNumeric && parsed > features.maximumRequestAmount;

  const oversizedFile = files.find((file) => file.size > MAX_FILE_BYTES);

  /**
   * What the applicant still has to do, in the order the form asks for it. Derived rather than
   * checked at submit time: a disabled button with no reason beside it is the single most common
   * way a form like this wastes someone's afternoon.
   */
  const missing = useMemo(() => {
    if (!method) return [];

    const outstanding: string[] = [];

    if (method.requiresAccountNumber && !accountId) outstanding.push(t('wallet.needAccount'));
    if (!isNumeric || parsed <= 0 || belowMinimum || aboveMaximum) {
      outstanding.push(t('wallet.needAmount'));
    }
    if (method.requiresProofDocument && files.length === 0) outstanding.push(t('wallet.needProof'));
    outstanding.push(...missingDocumentItems(documents, documentFiles, documentValues, t));

    return outstanding;
  }, [
    method,
    accountId,
    isNumeric,
    parsed,
    belowMinimum,
    aboveMaximum,
    files,
    documents,
    documentFiles,
    documentValues,
    t,
  ]);

  const isValid = useMemo(() => {
    if (!method) return false;
    if (missing.length > 0) return false;
    if (oversizedFile) return false;
    return true;
  }, [method, missing, oversizedFile]);

  function submit() {
    if (!method) return;

    create.mutate(
      {
        currencyId,
        paymentMethodId: method.id,
        paymentMethodAccountId: accountId,
        amount: parsed,
        note: note.trim() || null,
        files,
        documents: documentFiles,
        // Only the fields of this method's documents; nothing left over from another one.
        values: Object.fromEntries(
          documents
            .flatMap((document) => document.fields)
            .map((field) => [field.id, documentValues[field.id] ?? '']),
        ),
      },
      { onSuccess: onSubmitted },
    );
  }

  return (
    <div className="space-y-5" data-testid="deposit-form">
      <div className="space-y-5">
        {available.length > 0 && <StepProgress step={step} />}

        {methods.isPending && (
          <p className="text-sm text-muted-foreground">{t('common.loading')}</p>
        )}

        {!methods.isPending && available.length === 0 && (
          <Alert variant="info">{t('wallet.noPaymentMethods')}</Alert>
        )}

        {step === 1 && available.length > 0 && (
          <TypePicker types={types} selectedId={typeId} onPick={chooseType} />
        )}

        {step === 2 && type && (
          <MethodPicker type={type} selectedId={methodId} onPick={setMethodId} />
        )}

        {method && (
          <>
            {/* One line naming what was chosen, with the way back to change it. It replaces the
                dropdown that used to stay on screen repeating the provider the panel below it
                already named. */}
            <ChosenMethod method={method} onChange={goBack} />

            <MethodSummary method={method} />

            {method.requiresAccountNumber && (
              <AccountPicker
                accounts={method.accounts}
                selectedId={accountId}
                onSelect={setAccountId}
              />
            )}

            <Field label={t('wallet.amount')} htmlFor="deposit-amount">
              <div className="relative">
                {/* The currency sits inside the control: an amount box on a page that deals in
                    two currencies should never leave which one in doubt. */}
                <span
                  className="pointer-events-none absolute inset-y-0 start-0 flex items-center ps-3 text-sm font-medium text-muted-foreground"
                  aria-hidden="true"
                >
                  {currency}
                </span>
                <Input
                  id="deposit-amount"
                  type="number"
                  inputMode="decimal"
                  min={features.minimumRequestAmount}
                  max={features.maximumRequestAmount}
                  step="0.01"
                  value={amount}
                  onChange={(event) => setAmount(event.target.value)}
                  data-testid="deposit-amount"
                  className="ps-14 text-base font-semibold"
                />
              </div>
            </Field>

            <p className="-mt-3 text-xs text-muted-foreground">
              {t('wallet.amountLimits', {
                min: formatCurrency(features.minimumRequestAmount, currency, locale),
                max: formatCurrency(features.maximumRequestAmount, currency, locale),
              })}
            </p>

            {method.requiresProofDocument && <ProofPicker files={files} onChange={setFiles} />}

            <DepositDocuments
              documents={documents}
              files={documentFiles}
              values={documentValues}
              onFilesChange={setDocumentFiles}
              onValuesChange={setDocumentValues}
            />

            <Field label={t('wallet.requestNote')} htmlFor="deposit-note">
              <Input
                id="deposit-note"
                maxLength={1000}
                placeholder={t('wallet.depositNotePlaceholder')}
                value={note}
                onChange={(event) => setNote(event.target.value)}
              />
            </Field>

            {belowMinimum && (
              <Alert variant="error">
                {t('wallet.belowMinimum', {
                  min: formatCurrency(features.minimumRequestAmount, currency, locale),
                })}
              </Alert>
            )}

            {aboveMaximum && (
              <Alert variant="error">
                {t('wallet.aboveMaximum', {
                  max: formatCurrency(features.maximumRequestAmount, currency, locale),
                })}
              </Alert>
            )}

            {oversizedFile && (
              <Alert variant="error">
                {t('wallet.proofTooLarge', { name: oversizedFile.name })}
              </Alert>
            )}

            {/* Stated plainly rather than left to a greyed-out button. */}
            {missing.length > 0 && (
              <div className="rounded-xl bg-muted px-4 py-3" data-testid="deposit-missing">
                <p className="text-sm font-medium">{t('wallet.stillNeeded')}</p>
                <ul className="mt-1.5 space-y-1">
                  {missing.map((item) => (
                    <li key={item} className="flex items-start gap-2 text-sm text-muted-foreground">
                      <Circle
                        className="mt-1.5 size-1.5 shrink-0 fill-current"
                        aria-hidden="true"
                      />
                      {item}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Nothing is credited until someone checks it; saying so up front prevents the
                "where is my money" message an hour later. */}
            <p className="text-xs leading-relaxed text-muted-foreground">
              {t('wallet.approvalNotice')}
            </p>

            {create.isError && <Alert variant="error">{toMessage(create.error)}</Alert>}
          </>
        )}
      </div>

      {/* The form's own actions, beneath it rather than in a dialog footer. */}
      <div className="flex flex-wrap justify-end gap-3 border-t border-border pt-5">
        <Button variant="outline" onClick={goBack} data-testid="deposit-back">
          {step === 1 ? t('common.cancel') : t('common.back')}
        </Button>

        {/* Only offered once there is something to send. A permanently visible, permanently
              disabled submit on the first screen reads as a broken button rather than as a step
              that has not been reached yet. */}
        {step === 3 && (
          <Button
            disabled={!isValid || create.isPending}
            data-testid="confirm-deposit"
            onClick={submit}
          >
            {create.isPending && <Spinner />}
            {t('wallet.submitRequest')}
          </Button>
        )}
      </div>
    </div>
  );
}

/** What paying through this method involves, at a glance. */
function MethodIcon({ method }: { method: PaymentMethodOptionDto }) {
  const Icon = method.requiresBarcode
    ? QrCode
    : method.requiresBank
      ? Landmark
      : method.requiresAccountNumber
        ? Wallet
        : ExternalLink;

  return <Icon className="size-5" aria-hidden="true" />;
}

/**
 * Where the applicant is in the three questions, and how much is left.
 *
 * A bar rather than a line of text alone, because the useful thing at a glance is how much of this
 * is still ahead — a form that says "step 1 of 3" in the same grey as everything else answers that
 * only once somebody stops to read it.
 */
function StepProgress({ step }: { step: 1 | 2 | 3 }) {
  const { t } = useTranslation();

  const label =
    step === 3
      ? 'wallet.stepConfirm'
      : step === 2
        ? 'wallet.stepChooseMethod'
        : 'wallet.stepChooseType';

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-1.5" aria-hidden="true">
        {[1, 2, 3].map((index) => (
          <span
            key={index}
            className={cn(
              'h-1 flex-1 rounded-full transition-colors',
              index <= step ? 'bg-primary' : 'bg-muted',
            )}
          />
        ))}
      </div>

      <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
        {t('wallet.stepOf', { current: step, total: 3 })}
        {' · '}
        {t(label)}
      </p>
    </div>
  );
}

/**
 * One selectable card, shared by both picker steps so choosing a kind and choosing a provider look
 * and behave identically rather than being a grid of cards followed by a dropdown.
 *
 * The whole card is the control. A radio dot beside a card invites people to aim at the dot, which
 * is the smallest target on screen; here the selected state is carried by the border and a tick,
 * and the real radio stays for assistive technology and keyboard use.
 */
function ChoiceCard({
  name,
  icon,
  title,
  caption,
  checked,
  onPick,
  testId,
}: {
  name: string;
  icon: ReactNode;
  title: string;
  caption?: string;
  checked: boolean;
  onPick: () => void;
  testId: string;
}) {
  return (
    <label
      className={cn(
        'group relative flex cursor-pointer items-center gap-3 rounded-xl border p-3 transition',
        'focus-within:ring-2 focus-within:ring-primary focus-within:ring-offset-1',
        checked
          ? 'border-primary bg-primary/5 shadow-sm'
          : 'border-border hover:border-primary/60 hover:bg-muted',
      )}
    >
      <input
        type="radio"
        name={name}
        checked={checked}
        onChange={onPick}
        data-testid={testId}
        className="sr-only"
      />

      <span
        className={cn(
          'flex size-10 shrink-0 items-center justify-center rounded-lg transition-colors',
          checked ? 'bg-primary/10 text-primary' : 'bg-muted text-muted-foreground',
        )}
      >
        {icon}
      </span>

      <span className="min-w-0 flex-1">
        {/* Wraps rather than truncates: a provider whose name is cut to "External Payme..." is a
            choice somebody has to guess at. */}
        <span className="block font-medium leading-snug">{title}</span>
        {caption && <span className="mt-0.5 block text-xs text-muted-foreground">{caption}</span>}
      </span>

      <span
        className={cn(
          'flex size-5 shrink-0 items-center justify-center rounded-full border transition',
          checked ? 'border-primary bg-primary text-white' : 'border-border',
        )}
        aria-hidden="true"
      >
        {checked && <Check className="size-3.5" strokeWidth={3} />}
      </span>
    </label>
  );
}

/**
 * Step one: what kind of payment.
 *
 * The first thing somebody settles is whether they are sending a bank transfer or paying from a
 * wallet — not which of three bank accounts. Each card is drawn from the first method of its type,
 * because everything the icon reflects is a property of the type they share.
 */
function TypePicker({
  types,
  selectedId,
  onPick,
}: {
  types: { id: string; name: string; methods: PaymentMethodOptionDto[] }[];
  selectedId: string | null;
  onPick: (id: string) => void;
}) {
  const { t } = useTranslation();

  return (
    <fieldset>
      <legend className="mb-3 text-sm text-muted-foreground">
        {t('wallet.choosePaymentType')}
      </legend>

      <div className="grid gap-2 sm:grid-cols-2">
        {types.map((type) => (
          <ChoiceCard
            key={type.id}
            name="deposit-payment-type"
            icon={<MethodIcon method={type.methods[0]!} />}
            title={type.name}
            // A count is worth saying only where it is a choice; "1 to choose from" against every
            // card is noise that pushes the names apart for nothing.
            caption={
              type.methods.length > 1
                ? t('wallet.methodsAvailable', { n: type.methods.length })
                : undefined
            }
            checked={type.id === selectedId}
            onPick={() => onPick(type.id)}
            testId={`payment-type-${type.id}`}
          />
        ))}
      </div>
    </fieldset>
  );
}

/**
 * Step two: which provider of that kind.
 *
 * Cards, matching the step before it. It was a dropdown, which hid every option but one behind a
 * click at exactly the moment the applicant is comparing them — and a type with a single provider
 * never reaches this step at all now, so the list is only ever shown when there is a real choice.
 */
function MethodPicker({
  type,
  selectedId,
  onPick,
}: {
  type: { id: string; name: string; methods: PaymentMethodOptionDto[] };
  selectedId: string | null;
  onPick: (id: string) => void;
}) {
  const { t } = useTranslation();

  return (
    <fieldset>
      <legend className="mb-3 text-sm text-muted-foreground">
        {t('wallet.chooseMethodInType', { type: type.name })}
      </legend>

      <div className="grid gap-2">
        {type.methods.map((method) => (
          <ChoiceCard
            key={method.id}
            name="deposit-payment-method"
            icon={<MethodIcon method={method} />}
            title={method.name}
            caption={method.description ?? undefined}
            checked={method.id === selectedId}
            onPick={() => onPick(method.id)}
            testId={`payment-method-${method.id}`}
          />
        ))}
      </div>
    </fieldset>
  );
}

/** What was chosen, and the way back to change it. */
function ChosenMethod({
  method,
  onChange,
}: {
  method: PaymentMethodOptionDto;
  onChange: () => void;
}) {
  const { t } = useTranslation();

  return (
    <div className="flex items-center gap-3 rounded-xl border border-primary/30 bg-primary/5 p-3">
      <span className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary">
        <MethodIcon method={method} />
      </span>

      <span className="min-w-0 flex-1">
        <span className="block font-medium leading-snug">{method.name}</span>
        <span className="block text-xs text-muted-foreground">{method.typeName}</span>
      </span>

      <Button variant="ghost" size="sm" onClick={onChange} data-testid="deposit-change-method">
        {t('wallet.change')}
      </Button>
    </div>
  );
}

/**
 * What the chosen method tells the applicant to do before they fill anything in.
 *
 * The name and the type are not repeated here — ChosenMethod states both directly above. This panel
 * carries only what the administrator wrote about paying through this provider, and renders nothing
 * at all when they wrote none, rather than an empty box.
 */
function MethodSummary({ method }: { method: PaymentMethodOptionDto }) {
  const { t } = useTranslation();

  const hasLink = method.requiresExternalUrl && method.externalUrl;
  if (!method.description && !method.publicNote && !hasLink) return null;

  return (
    <div className="space-y-2 rounded-xl border border-border bg-muted/50 p-3">
      {method.description && (
        <p className="text-sm leading-relaxed text-muted-foreground">{method.description}</p>
      )}

      {method.publicNote && (
        <p className="text-sm leading-relaxed text-foreground/80">{method.publicNote}</p>
      )}

      {/* Keyed on what the method asks for rather than on its kind: a transfer provider may offer
          a link alongside its receiving numbers, and both then belong on the page. */}
      {hasLink && (
        <a
          href={method.externalUrl!}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-1.5 rounded-lg bg-primary px-3 py-2 text-sm font-medium text-white transition-colors hover:bg-primary/90"
          data-testid="payment-external-link"
        >
          <ExternalLink className="size-4" aria-hidden="true" />
          {t('wallet.openPaymentPage')}
        </a>
      )}
    </div>
  );
}

/** Which of the configured accounts the applicant actually transferred to. */
function AccountPicker({
  accounts,
  selectedId,
  onSelect,
}: {
  accounts: PaymentAccountOptionDto[];
  selectedId: string | null;
  onSelect: (id: string) => void;
}) {
  const { t } = useTranslation();
  const [copied, setCopied] = useState<string | null>(null);

  async function copy(value: string) {
    try {
      await navigator.clipboard.writeText(value);
      setCopied(value);
      window.setTimeout(() => setCopied(null), 2000);
    } catch {
      // Clipboard access can be refused; the number is on screen to be typed either way.
    }
  }

  return (
    <fieldset className="space-y-2">
      <legend className="text-sm font-medium">{t('wallet.chooseAccount')}</legend>
      <p className="text-xs text-muted-foreground">{t('wallet.chooseAccountHint')}</p>

      <ul className="space-y-2">
        {accounts.map((account) => (
          <li key={account.id}>
            {/* Same card treatment as the two steps before it, so "pick one of these" looks like
                the same gesture throughout the form. The number is the largest thing on the card:
                it is what somebody is about to copy into their banking app. */}
            <label
              className={cn(
                'group flex cursor-pointer items-start gap-3 rounded-xl border p-3 transition',
                'focus-within:ring-2 focus-within:ring-primary focus-within:ring-offset-1',
                selectedId === account.id
                  ? 'border-primary bg-primary/5 shadow-sm'
                  : 'border-border hover:border-primary/60 hover:bg-muted',
              )}
            >
              <input
                type="radio"
                name="deposit-account"
                className="sr-only"
                checked={selectedId === account.id}
                onChange={() => onSelect(account.id)}
                data-testid={`deposit-account-${account.id}`}
              />

              <span className="min-w-0 flex-1">
                <span className="block text-xs font-medium uppercase tracking-wide text-muted-foreground">
                  {account.label}
                </span>

                <span className="mt-1 flex items-center gap-2">
                  <span className="font-mono text-base font-semibold text-foreground" dir="ltr">
                    {account.accountNumber}
                  </span>
                  <button
                    type="button"
                    onClick={(event) => {
                      event.preventDefault();
                      void copy(account.accountNumber);
                    }}
                    aria-label={t('common.copy')}
                    className="rounded p-1 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                  >
                    {copied === account.accountNumber ? (
                      <Check className="size-4 text-primary" aria-hidden="true" />
                    ) : (
                      <Copy className="size-4" aria-hidden="true" />
                    )}
                  </button>
                </span>

                {account.bankName && (
                  <span className="block text-xs text-muted-foreground">{account.bankName}</span>
                )}

                {account.accountHolder && (
                  <span className="block text-xs text-muted-foreground">
                    {account.accountHolder}
                  </span>
                )}

                {account.hasBarcode && (
                  <AccountBarcode accountId={account.id} label={account.label} />
                )}
              </span>

              <span
                className={cn(
                  'mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full border transition',
                  selectedId === account.id
                    ? 'border-primary bg-primary text-white'
                    : 'border-border',
                )}
                aria-hidden="true"
              >
                {selectedId === account.id && <Check className="size-3.5" strokeWidth={3} />}
              </span>
            </label>
          </li>
        ))}
      </ul>
    </fieldset>
  );
}

/** The receipts proving the transfer landed. */
function ProofPicker({ files, onChange }: { files: File[]; onChange: (files: File[]) => void }) {
  const { t } = useTranslation();
  const inputRef = useRef<HTMLInputElement>(null);

  return (
    <fieldset className="space-y-2">
      <legend className="text-sm font-medium">{t('wallet.proof')}</legend>
      <p className="text-xs text-muted-foreground">{t('wallet.proofHint')}</p>

      <input
        ref={inputRef}
        type="file"
        multiple
        accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png"
        className="hidden"
        data-testid="deposit-proof-input"
        onChange={(event) => {
          const picked = Array.from(event.target.files ?? []);
          event.target.value = '';
          onChange([...files, ...picked].slice(0, MAX_FILES));
        }}
      />

      <Button
        type="button"
        variant="outline"
        size="sm"
        disabled={files.length >= MAX_FILES}
        onClick={() => inputRef.current?.click()}
      >
        <Paperclip className="size-4" aria-hidden="true" />
        {t('wallet.attachProof')}
      </Button>

      {files.length > 0 && (
        <ul className="space-y-1">
          {files.map((file, index) => (
            <li
              key={`${file.name}-${index}`}
              className="flex items-center justify-between gap-2 rounded-lg bg-muted px-3 py-1.5 text-sm"
            >
              <span className="min-w-0 truncate">{file.name}</span>
              <button
                type="button"
                aria-label={t('common.remove')}
                onClick={() => onChange(files.filter((_, i) => i !== index))}
                className="shrink-0 rounded p-0.5 text-muted-foreground hover:text-destructive"
              >
                <X className="size-4" aria-hidden="true" />
              </button>
            </li>
          ))}
        </ul>
      )}
    </fieldset>
  );
}
